import logicalOwnerFixture from "../../🧫️fixtures/🪶️sqlite/🧠️logical-owner/🔣️.json";
import logicalOwnerSchema from "../../🧫️fixtures/🪶️sqlite/🧠️logical-owner/🧬️schema/🔣️.json";
import { parseCsvSnapshot } from "../../🟦️.ts";
test("Csv complete logical owner preserves authored metadata and empty records in independent SQLite",async()=>{
 const validate=new Ajv2020({strict:true,allErrors:true}).compile(logicalOwnerSchema);expect(validate(logicalOwnerFixture)).toBe(true);
 expect(validate({...logicalOwnerFixture,unexpected:true})).toBe(false);
 expect(validate({...logicalOwnerFixture,snapshots:[{...logicalOwnerFixture.snapshots[0],hasHeader:"false"},logicalOwnerFixture.snapshots[1]]})).toBe(false);
 for(const [index,owner]of logicalOwnerFixture.snapshots.entries()){
  expect(parseCsvSnapshot(owner)).toEqual(owner);
  const file=await exportSqliteDatabase(await csvSnapshotToSqliteDatabase(owner));const independent=Database.deserialize(file);
  try{
   expect(independent.query("PRAGMA integrity_check").get()).toEqual({integrity_check:"ok"});
   expect(independent.query("PRAGMA foreign_key_check").all()).toEqual([]);
   expect(independent.query("SELECT schema,has_header FROM csv_document").get()).toEqual({schema:owner.schema,has_header:Number(owner.hasHeader)});
   expect(independent.query("SELECT r.ordinal,count(f.id) AS fields FROM csv_record r LEFT JOIN csv_field f ON f.record_id=r.id GROUP BY r.id ORDER BY r.ordinal").all()).toEqual(owner.records.map((record,ordinal)=>({ordinal,fields:record.fields.length})));
   expect(independent.query("SELECT f.value,f.quoted FROM csv_field f JOIN csv_record r ON r.id=f.record_id ORDER BY r.ordinal,f.ordinal").all()).toEqual(owner.records.flatMap(record=>record.fields.map(field=>({value:field.value,quoted:Number(field.quoted)}))));
   expect(await csvSnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(independent.serialize())))).toEqual(owner);
   if(index===logicalOwnerFixture.edit.snapshotIndex){independent.run(logicalOwnerFixture.edit.query);expect(await csvSnapshotFromSqliteDatabase(await importSqliteDatabase(new Uint8Array(independent.serialize())))).toEqual({...owner,hasHeader:true});}
  }finally{independent.close();}
 }
 console.log("[DEBUG] Csv complete logical owners retained literal schema, header flag, quote flags and zero-field record occurrences through independent SQLite");
});

#[semio_framework_async_macros::async_test]
async fn sqlite_snapshot_csv_complete_logical_owner_erased_factory_preserves_every_literal_field(){
 use semio_framework_os_kernel::io::ArtifactDialect;
 use store::sqlite_snapshot::SnapshotEncoding;
 let fixture:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🧠️logical-owner/🔣️.json")).unwrap();
 semio_framework_plugin::Plugin::<semio_framework_plugin::app::NoPluginApp>::builder("stdio").label("Csv complete logical owner").version("0.0.1").package_id("semio:stdio").artifact(crate::declaration(crate::definition().unwrap()).unwrap()).try_build().unwrap();
 let codec=store::document_codec(crate::STDIO_CSV_DOCUMENT_SCHEMA).await.unwrap().unwrap();let provider=codec.snapshot_sqlite.as_ref().unwrap();assert_eq!(provider.snapshot_type,Some(std::any::TypeId::of::<CsvSnapshot>()));
 let dialect=ArtifactDialect{artifact_kind:"s.stdio.csv".into(),standard:"rfc4180".into(),subset:"*".into()};
 for input in fixture["snapshots"].as_array().unwrap(){
  let snapshot=CsvSnapshot{schema:input["schema"].as_str().unwrap().into(),has_header:input["hasHeader"].as_bool().unwrap(),records:input["records"].as_array().unwrap().iter().map(|record|CsvRecord{fields:record["fields"].as_array().unwrap().iter().map(|field|CsvField{value:field["value"].as_str().unwrap().into(),quoted:field["quoted"].as_bool().unwrap()}).collect()}).collect()};
  let expected=snapshot.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();
  for encoding in[SnapshotEncoding::Binary,SnapshotEncoding::Text]{
   let input=csv_native_payload(&snapshot,encoding);let admitted=CsvSnapshot::decode_sqlite_snapshot_native(&input,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(admitted,snapshot,"native owner admission must retain every authored field before erased export");
   let projected=(provider.export)(&codec.schema,&dialect,&input,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;assert_eq!(projected,expected);
   let output=(provider.import)(&codec.schema,&dialect,projected,encoding,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap().value;
   let restored=CsvSnapshot::decode_sqlite_snapshot_native(&output,&mut SqliteSnapshotControl::new(&mut |_|true,Default::default())).unwrap();assert_eq!(restored,snapshot);
   let ordinary=match output{store::io_schema::IoPayload::Binary(bytes)=><CsvSnapshot as store::ArtifactPack>::decode_pack(&bytes).unwrap(),store::io_schema::IoPayload::Text(text)=><CsvSnapshot as store::ArtifactDsl>::parse_dsl(&text).unwrap()};assert_eq!(ordinary,snapshot);
  }
 }
 println!("[DEBUG] Csv actual erased factory preserved every complete logical owner in both native formats");
}
